import org.apache.commons.jxpath.ri.model.NodePointer;

import java.util.Locale;

import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.Mockito.*;

public class NamespacePointerTests {

    private CollectionPointer collectionPointer;
    private NodePointer parentPointer;
    private Object collection;

    @BeforeEach
    public void setUp() {
        parentPointer = mock(NodePointer.class);
        collection = new Object();
        collectionPointer = new CollectionPointer(parentPointer, collection);
    }

    @Test
    public void testNamespacePointerWholeCollection() {
        // Set up the collectionPointer to simulate WHOLE_COLLECTION
        collectionPointer = spy(collectionPointer);
        doReturn(CollectionPointer.WHOLE_COLLECTION).when(collectionPointer).getIndex();

        NodePointer result = collectionPointer.namespacePointer("someNamespace");
        assertNull(result, "Expected namespacePointer to return null for WHOLE_COLLECTION");
    }

    @Test
    public void testNamespacePointerWithIndex() {
        // Set up the collectionPointer to simulate a specific index
        collectionPointer = spy(collectionPointer);
        doReturn(1).when(collectionPointer).getIndex();

        NodePointer valuePointer = mock(NodePointer.class);
        doReturn(valuePointer).when(collectionPointer).getValuePointer();
        NodePointer expectedNamespacePointer = mock(NodePointer.class);
        doReturn(expectedNamespacePointer).when(valuePointer).namespacePointer("someNamespace");

        NodePointer result = collectionPointer.namespacePointer("someNamespace");
        verify(valuePointer).namespacePointer("someNamespace");
    }
}

